{
  "queries": [
    {
      "doc_id": "ECN-2026-048: Change notice - Ring Rolling induction billet heater #1",
      "query": "Please provide the approval trail and signatures for this ECN, and confirm whether the risk assessment and test results validating the heater modification are attached or referenced."
    },
    {
      "doc_id": "QS-PROC-10: Machining surface finish (P2)",
      "query": "I need the latest revision and evidence that the surface finish acceptance criteria were reviewed by Quality; highlight where rework criteria versus reject criteria are defined."
    },
    {
      "doc_id": "SOP-P2-L3-03: First-article inspection - Machining line",
      "query": "What are the required records to be completed during first-article inspection, who must approve the first-article report, and where are those approvals stored?"
    },
    {
      "doc_id": "SOP-P3-L1-01: Line startup - Hot Forge line",
      "query": "List the mandatory pre-start checks and required signoffs for startup; also indicate any changes from the prior version and rationale for those changes."
    },
    {
      "doc_id": "QS-CFW-9335-36: Quality specification - gear blank CFW-9335-36 (8620)",
      "query": "Provide the critical inspection characteristics and measurement methods for this gear blank, and confirm whether the specification references any external standards."
    },
    {
      "doc_id": "SOP-P1-L2-04: Shift handover - Ring Rolling line",
      "query": "Describe the minimum information that must be handed over between shifts, required documentation, and evidence of adherence to the handover procedure."
    },
    {
      "doc_id": "SOP-P3-L3-01: Line startup - Machining line",
      "query": "What are the documented steps and responsible roles for the machining line startup, and is there a pre-start checklist that operators must sign?"
    },
    {
      "doc_id": "SOP-P2-L2-03: First-article inspection - Ring Rolling line",
      "query": "How does first-article inspection on the Ring Rolling line differ from the Machining line procedure, and where are disposition criteria recorded?"
    },
    {
      "doc_id": "QS-CFW-1931-62: Quality specification - gear blank CFW-1931-62 (8620)",
      "query": "Request the dimensional tolerances and heat treatment requirements for this gear blank, and indicate any customer-specific requirements noted in the spec."
    },
    {
      "doc_id": "QS-CFW-8404-30: Quality specification - flange blank CFW-8404-30 (4140)",
      "query": "Provide the nonconformance acceptance limits for surface defects and the inspection frequency; also confirm whether sampling plans are included."
    },
    {
      "doc_id": "QS-CFW-7855-84: Quality specification - valve body CFW-7855-84 (F316)",
      "query": "Where are the corrosion resistance or material traceability requirements documented for this valve body, and is a certificate of conformity required with shipments?"
    },
    {
      "doc_id": "SOP-P2-L1-05: Planned shutdown - Hot Forge line",
      "query": "Outline the steps for a planned shutdown, required permits, and post-shutdown verification activities; also request the checklist used for recording completion."
    },
    {
      "doc_id": "QS-CFW-4068-79: Quality specification - bearing ring CFW-4068-79 (52100)",
      "query": "I need the key hardness and microstructure acceptance criteria for this bearing ring and the method used to sample parts for hardness testing."
    },
    {
      "doc_id": "SOP-P2-L3-05: Planned shutdown - Machining line",
      "query": "Confirm who authorizes a planned shutdown on the machining line, what preventive maintenance tasks are mandated, and where work completion evidence is kept."
    },
    {
      "doc_id": "SOP-P3-L2-05: Planned shutdown - Ring Rolling line",
      "query": "Describe the isolation and lockout steps specific to the Ring Rolling line during planned shutdown and indicate required training or qualifications for personnel performing shutdown tasks."
    },
    {
      "doc_id": "SOP-P3-L2-01: Line startup - Ring Rolling line",
      "query": "What verification steps are required after startup to confirm the Ring Rolling line is back within process control, and which records must be completed within the first shift?"
    },
    {
      "doc_id": "ECN-2026-030: Change notice - Machining hydraulic forging press #2",
      "query": "Please provide the testing evidence and signoffs that validate the change to press #2, and list any affected work instructions that were updated as a result."
    },
    {
      "doc_id": "ECN-2026-046: Change notice - Machining induction billet heater #1",
      "query": "Who approved this ECN and what failure modes were considered in the implementation? Attach or point to any commissioning reports or validation records."
    },
    {
      "doc_id": "SOP-P2-L3-01: Line startup - Machining line",
      "query": "Is there a difference between this startup procedure and SOP-P3-L3-01? If so, provide a summary of differences and justification for separate documents."
    },
    {
      "doc_id": "QS-CFW-1159-60: Quality specification - track link CFW-1159-60 (15B37)",
      "query": "Request the mechanical property requirements and NDT expectations for the track link, and confirm whether material lot traceability is required through final inspection."
    }
  ]
}
